```tuo
fn checked_sub(take a: Int, take b: Int) -> Result[Int, Str] {
    if b > a {
        Err { error: "underflow" }
    } else {
        Ok { value: a - b }
    }
}

fn or_neg1(in r: Result[Int, Str]) -> Int {
    match r {
        Ok { value } => value,
        Err { error } => 0 - 1,
    }
}

spec checked_sub {
    then or_neg1(checked_sub(10, 3)) == 7;
    then or_neg1(checked_sub(3, 10)) == 0 - 1;
}
```

```tuo
fn first_even(take a: Int, take b: Int) -> Option[Int] {
    if a % 2 == 0 {
        Some { value: a }
    } else if b % 2 == 0 {
        Some { value: b }
    } else {
        None
    }
}

fn or_zero(in o: Option[Int]) -> Int {
    match o {
        Some { value } => value,
        None => 0,
    }
}

spec first_even {
    then or_zero(first_even(3, 4)) == 4;
    then or_zero(first_even(2, 7)) == 2;
    then or_zero(first_even(1, 3)) == 0;
}
```

Construct Option payloads with named fields: `Some { value: a }`, never `Some(a)`.

